const $=s=>document.querySelector(s), fa=n=>Number(n).toLocaleString('fa-IR'), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
