const norm=normalizeSearch;
const storage={get(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('ذخیره در این مرورگر ممکن نیست.')}}};
const state={products:[],shown:16,compare:[],point:storage.get('point',{lat:35.7007,lon:51.4091,label:'تهران، مرکز شهر'}),plan:storage.get('plan',[]),notes:storage.get('notes',{}),excluded:new Set(),selected:null,query:'',seq:0};
let searchAbort,navigation=0,catalogScroll=0,pageOffset=0,pageHasMore=false,pageTotal=0,pageEngine=null,loadingPage=null,searchParams={};const productCache=new Map(),productInflight=new Map();
const cache=new Map();let shops={},meta={},guide={category:'کفش',use:'روزمره',budget:''};
async function json(url){if(!cache.has(url))cache.set(url,fetch(url,{cache:'no-cache',signal:AbortSignal.timeout(30000)}).then(async r=>{if(!r.ok)throw Error('خطا در دریافت اطلاعات');const payload=await r.json();const bytes=Uint8Array.from(atob(payload.gzip),c=>c.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text())}).catch(e=>{cache.delete(url);throw e}));return cache.get(url)}
function toast(t){const node=$('#toast'),dialog=$('#modal'),host=dialog.open?dialog:document.body;if(node.parentElement!==host)host.append(node);node.textContent=t;node.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.style.display='none',4200)}
function modal(html){modalEpoch++;$('#toast').style.display='none';$('#modalBody').innerHTML=html; if(!$('#modal').open)$('#modal').showModal()}
