$('#closeModal').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close()});
$('#modal').addEventListener('close',()=>{modalEpoch++;const node=$('#toast');if(node.parentElement===$('#modal')){node.style.display='none';document.body.append(node)}});
function img(p,cls=''){const fallback=`<span class="placeholder">${icon('picture')}<small>تصویر در دسترس نیست</small></span>`;return p.image&&/^https:\/\//.test(p.image)?`<img class="${esc(cls)}" src="${esc(p.image)}" alt="${esc(p.title)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" onerror="this.outerHTML=${esc(JSON.stringify(fallback))}">`:fallback}
function distance(s){if(!s||!Number.isFinite(s.lat)||!Number.isFinite(s.lon))return null;let rad=x=>x*Math.PI/180,a=rad(s.lat-state.point.lat),b=rad(s.lon-state.point.lon);return 6371*2*Math.asin(Math.sqrt(Math.sin(a/2)**2+Math.cos(rad(s.lat))*Math.cos(rad(state.point.lat))*Math.sin(b/2)**2))}
function visit(){const v=$('#visitTime').value;return v?new Date(v+'+03:30'):new Date()}
function hours(s){const h=visitStatus(s,visit());return {...h,text:h.open===null?'ساعت کاری نامشخص':h.open?'طبق برنامه باز است':'طبق برنامه بسته است'}}
function credit(s,o){return (s.payment_options||[]).filter(x=>x.channel==='in_person'&&(!x.min_price_toman||o.price>=x.min_price_toman)&&(!x.max_price_toman||o.price<=x.max_price_toman)&&(!x.category_names?.length||x.category_names.includes(o.category||state.selected?.category)))}
function qualifying(p){const matches=p.offers.filter(o=>{const s=shops[o.shop];if(!s||state.excluded.has(o.shop))return false;const b=parseAmount($('#budget').value),d=distance(s),r=+$('#radius').value;if(b&&(!o.price||o.price>b))return false;if(r<100&&(d===null||d>r))return false;if($('#credit').checked&&!credit(s,{...o,category:p.category}).length)return false;if($('#openOnly').checked&&hours(s).open!==true)return false;return true});const grouped=new Map();for(const o of matches){const old=grouped.get(o.shop);if(!old||(o.price||Infinity)<(old.price||Infinity))grouped.set(o.shop,o)}return [...grouped.values()]}
function productCard(p){const offers=qualifying(p),min=Math.min(...offers.map(x=>x.price).filter(x=>x>0));return `<article class="product">${companion?.favoriteButton(p)||''}<button class="image-btn" data-product="${p.id}" aria-label="مشاهده ${esc(p.title)}">${img(p)}</button><div class="card-body"><span class="category">${esc(p.category)}</span><button class="product-title" data-product="${p.id}">${esc(p.title)}</button><div class="price">${price(isFinite(min)?min:null)}</div><span class="sellers">در ${fa(offers.length)} فروشگاه · قیمت ثبت‌شده</span><div class="card-foot"><button data-product="${p.id}">فروشگاه‌ها ${icon('arrow')}</button><label><input type="checkbox" data-compare="${p.id}" aria-label="افزودن ${esc(p.title)} به مقایسه" ${state.compare.some(x=>x.id===p.id)?'checked':''}> مقایسه</label></div></div></article>`}
function render(){let ps=state.products.filter(p=>qualifying(p).length);const sort=$('#productSort').value;if(sort==='cheap')ps.sort((a,b)=>(Math.min(...qualifying(a).map(o=>o.price||Infinity)))-(Math.min(...qualifying(b).map(o=>o.price||Infinity))));if(sort==='sellers')ps.sort((a,b)=>qualifying(b).length-qualifying(a).length);$('#products').innerHTML=ps.length?ps.slice(0,state.shown).map(productCard).join(''):`<div class="empty"><b>${pageHasMore?'در گزینه‌های دریافت‌شده موردی پیدا نشد':'گزینه‌ای با این شرایط پیدا نشد'}</b><p>بودجه یا محدوده را بیشتر کن، یا فیلتر اعتبار و ساعت را بردار.</p><button data-reset>پاک کردن فیلترها</button></div>`;$('#more').hidden=!pageHasMore;$('#resultCount').textContent=`${fa(ps.length)} محصول مطابق شرایط در ${fa(state.products.length)} محصول دریافت‌شده`;
$('#activeFilters').textContent=[$('#credit').checked?'خرید اعتباری حضوری':'',$('#openOnly').checked?'باز در زمان مراجعه':'',parseAmount($('#budget').value)?'تا '+fa($('#budget').value)+' تومان':'',+$('#radius').value<100?'شعاع '+fa($('#radius').value)+' کیلومتر':''].filter(Boolean).join(' · ');companion?.refresh()}
function abortable(promise,signal){
 if(!signal)return promise;if(signal.aborted)return Promise.reject(signal.reason||new DOMException('Aborted','AbortError'));
 return new Promise((resolve,reject)=>{const aborted=()=>reject(signal.reason||new DOMException('Aborted','AbortError'));signal.addEventListener('abort',aborted,{once:true});promise.then(resolve,reject).finally(()=>signal.removeEventListener('abort',aborted))});
}
async function getProducts(ids,signal){
 const unique=[...new Set(ids)],missing=unique.filter(id=>!productCache.has(id)&&!productInflight.has(id));
 for(let i=0;i<missing.length;i+=24){const chunk=missing.slice(i,i+24);const request=fetch('/api/products?'+new URLSearchParams({ids:chunk.join(',')}),{signal:AbortSignal.timeout(30000)}).then(async r=>{if(!r.ok)throw Error('products_unavailable');const d=await r.json();for(const p of d.products)productCache.set(p.id,p);while(productCache.size>200)productCache.delete(productCache.keys().next().value)}).finally(()=>chunk.forEach(id=>productInflight.delete(id)));for(const id of chunk)productInflight.set(id,request)}
 await abortable(Promise.all([...new Set(unique.map(id=>productInflight.get(id)).filter(Boolean))]),signal);
 return ids.map(id=>productCache.get(id)).filter(Boolean);
}
function pageStatus(notice=''){const text=`${fa(pageTotal)} نتیجه پیدا شد · ${fa(state.products.length)} محصول دریافت شد. گزینه‌های بیشتر با درخواست تو بارگیری می‌شوند.`;$('#status').textContent=notice?notice+' · '+text:text}
async function fetchPage(offset,signal){
 const params={...searchParams,offset,limit:24,...(pageEngine==='inverted'?{engine:'inverted'}:{})};
 const r=await fetch('/api/search?'+new URLSearchParams(params),{signal:AbortSignal.any([signal,AbortSignal.timeout(60000)])});if(!r.ok)throw Error('search_unavailable');return r.json();
}
function acceptPage(d,offset){pageOffset=Number.isInteger(d.nextOffset)?d.nextOffset:offset+d.results.length;pageHasMore=typeof d.hasMore==='boolean'?d.hasMore:pageOffset<(d.total??0);pageTotal=d.total??d.results.length;pageEngine=d.engine||pageEngine;state.shown=state.products.length}
async function loadMore(){
 if(!pageHasMore||loadingPage?.seq===state.seq)return;
 if(!searchAbort||searchAbort.signal.aborted)searchAbort=new AbortController();
 const seq=state.seq,button=$('#more'),signal=searchAbort.signal;loadingPage={seq};button.disabled=true;button.textContent='در حال دریافت…';button.setAttribute('aria-busy','true');
 try{const d=await fetchPage(pageOffset,signal);if(seq!==state.seq)return;
  if(pageEngine&&d.engine&&pageEngine!==d.engine){await search(state.query,{engine:d.engine,notice:'نتایج به‌روز شدند'});return}
  const items=await getProducts(d.results.map(r=>r[0]),signal);if(seq!==state.seq)return;
  const seen=new Set(state.products.map(p=>p.id));state.products.push(...items.filter(p=>!seen.has(p.id)));acceptPage(d,pageOffset);render();pageStatus();
  if(button.hidden){$('#status').tabIndex=-1;$('#status').focus({preventScroll:true})}
 }catch(e){if(seq===state.seq&&e.name!=='AbortError'){toast('دریافت گزینه‌های بیشتر ممکن نشد؛ دوباره بزن.');$('#status').textContent='گزینه‌های قبلی حفظ شدند. برای دریافت ادامه، دوباره نمایش بیشتر را بزن.'}}
 finally{if(seq===state.seq){loadingPage=null;button.disabled=false;button.textContent='نمایش محصولات بیشتر';button.removeAttribute('aria-busy')}}
}
async function search(q,{engine,notice=''}={}){
 navigation++;document.body.classList.remove('home');const intent=parseSearchIntent(q);q=intent.query;if(intent.budget)$('#budget').value=intent.budget;$('#query').value=q;
 searchAbort?.abort();searchAbort=new AbortController();const signal=searchAbort.signal,seq=++state.seq;state.query=q;state.shown=24;state.products=[];pageOffset=0;pageHasMore=false;pageEngine=engine||null;loadingPage=null;searchParams={q,budget:parseAmount($('#budget').value),sort:$('#productSort').value};showCatalog();$('#more').hidden=true;$('#more').disabled=false;$('#more').removeAttribute('aria-busy');$('#more').textContent='نمایش محصولات بیشتر';
 $('#resultTitle').textContent=q?`نتایج جستجو برای «${q}»`:'محصولات پیشنهادی';$('#status').textContent='در حال پیدا کردن محصولات…';$('#products').setAttribute('aria-busy','true');$('#products').innerHTML=Array(8).fill('<div class="skeleton"></div>').join('');
 try{const [d]=await Promise.all([fetchPage(0,signal),ensureCatalogData()]);if(seq!==state.seq)return;
  const items=await getProducts(d.results.map(r=>r[0]),signal);if(seq!==state.seq)return;state.products=items;acceptPage(d,0);render();companion?.searched(q);pageStatus(notice);
 }catch(e){if(seq===state.seq&&e.name!=='AbortError'){$('#status').textContent='دریافت داده‌ها ناموفق بود. دوباره جستجو کن.';$('#products').innerHTML='<div class="empty">داده‌ها بارگیری نشدند.<button id="retrySearch">تلاش دوباره</button></div>';$('#retrySearch').onclick=()=>search(q)}}
 finally{if(seq===state.seq)$('#products').removeAttribute('aria-busy')}
}
function showCatalog(){companion?.catalog();$('#catalog').hidden=false;$('#detail').hidden=true;$('#step2').classList.remove('active');$('#step3').classList.remove('active')}
async function openProduct(id){if(!$('#catalog').hidden)catalogScroll=window.scrollY;const nav=++navigation;searchAbort?.abort();state.seq++;loadingPage=null;$('#more').disabled=false;$('#more').removeAttribute('aria-busy');$('#more').textContent='نمایش محصولات بیشتر';document.body.classList.remove('home');let p=state.products.find(x=>x.id===id)||state.compare.find(x=>x.id===id);try{await ensureCatalogData();if(nav!==navigation)return;if(!p){p=(await getProducts([id]))[0];if(!p)throw Error()}if(nav!==navigation)return;state.selected=p;companion?.viewed(p);$('#catalog').hidden=true;$('#detail').hidden=false;$('#step2').classList.add('active');renderDetail();$('#detail').scrollIntoView({behavior:'smooth',block:'start'})}catch{if(nav===navigation)toast('دریافت محصول ممکن نشد؛ دوباره امتحان کن.')}}
function offerAge(o){let d=new Date(o.updated);return isNaN(d)?'زمان تغییر قیمت نامشخص':formatDate(d)}
function ranked(p){let os=qualifying(p).map(o=>({...o,s:shops[o.shop]})),sort=$('#shopSort')?.value||'balanced',prices=os.map(o=>o.price).filter(x=>x>0),min=Math.min(...prices);os.forEach(o=>{let dist=distance(o.s),h=hours(o.s);o.score=(o.price&&isFinite(min)?o.price/min:4)*.45+(dist===null?2:Math.min(dist/10,3))*.35+(h.open===true?0:h.open===false?1:.5)*.2});if(sort==='price')os.sort((a,b)=>(a.price||Infinity)-(b.price||Infinity));else if(sort==='distance')os.sort((a,b)=>(distance(a.s)??Infinity)-(distance(b.s)??Infinity));else os.sort((a,b)=>a.score-b.score);return os}
function shopCard(o,i){let s=o.s,d=distance(s),h=hours(s),c=credit(s,o),note=state.notes[state.selected.id+o.shop];return `<article class="shop-card"><div><span class="reason">${i===0?'پیشنهاد اول در ترتیب فعلی · ':''}${d===null?'فاصله نامشخص':fa(d.toFixed(1))+' کیلومتر فاصله مستقیم'}</span><h3>${esc(s.name)} <span class="badge gray">نام دیتاست</span></h3><p class="small">گزینهٔ فروشنده: ${esc(o.title||state.selected.title)}</p>${o.description?`<details class="offer-description"><summary>توضیحات فروشنده</summary><p>${esc(o.description)}</p></details>`:''}<p>⌖ ${esc(s.address||s.location_label||'آدرس نامشخص')}</p><span class="badge ${h.open===true?'green':'gray'}">${esc(h.text)}</span><div class="chips">${c.map(x=>`<span class="chip">${esc(x.provider_name)} · پذیرش حضوری ثبت‌شده</span>`).join('')}${!c.length?'<span class="chip">اعتبار حضوری تأیید نشده</span>':''}</div><div class="shop-actions"><button data-kit-shop="${o.shop}">پیش از حرکت</button><button data-route-shop="${o.shop}">⌖ مسیریابی</button><button data-save="${o.shop}">♡ ذخیره در برنامه</button><details class="shop-more"><summary>بیشتر</summary><button data-verify="${o.shop}">ثبت نتیجهٔ پیگیری</button><button data-address="${o.shop}">آدرس داخل پاساژ</button><button data-fail="${o.shop}">بسته بود / پاسخ نداد</button></details></div>${note?`<p class="small">یادداشت شخصی شما: ${esc(note.text)} · ${esc(formatDate(note.at,true))}</p>`:''}</div><div class="shop-meta"><div class="shop-price">${price(o.price)}</div><p>قیمت ثبت‌شده در دیتاست</p><span class="badge">موجودی تأیید نشده</span><p class="small">آخرین تغییر قیمت: ${esc(offerAge(o))}</p><p class="small">باز بودن بر اساس برنامهٔ ثبت‌شده است، نه تأیید زنده.</p></div></article>`}
function renderDetail(){let p=state.selected,sort=$('#shopSort')?.value||'balanced';$('#detail').innerHTML=`<button class="back" id="backCatalog">→ بازگشت به نتایج</button><div class="detail-top"><div>${img(p)}${(p.images||[]).length>1?`<button id="productGallery" class="outline">همهٔ تصاویر (${fa(p.images.length)})</button>`:''}</div><div><p class="small">${esc(p.category)} ${p.brand?' / '+esc(p.brand):''}</p><h2>${esc(p.title)}</h2><div class="price">از ${price(p.min)}</div><p>قیمت ثبت‌شده؛ پیش از مراجعه استعلام بگیر.</p><div class="chips">${p.specs.slice(0,5).map(x=>`<span class="chip">${esc(x.key)}: ${esc(x.value)}</span>`).join('')}</div><div class="modal-actions"><button id="shareProduct">اشتراک محصول ↗</button><button id="specsBtn" class="outline">مشخصات کامل موجود</button><button id="compareThis">⇄ افزودن به مقایسه</button><button id="editFilters">تغییر شرایط خرید</button></div></div></div><div class="shop-toolbar"><div><h2>فروشگاه‌های این محصول</h2><p class="small">رتبه‌بندی متناسب با قیمت، فاصله و زمان مراجعه · مبدأ: ${esc(state.point.label)}</p></div><select id="shopSort" aria-label="ترتیب فروشگاه‌ها"><option value="balanced">پیشنهاد متعادل</option><option value="price">ارزان‌ترین قیمت</option><option value="distance">نزدیک‌ترین فروشگاه</option></select></div><div id="shopList"></div>`;$('#productGallery')?.addEventListener('click',()=>openDeferred(async()=>{const [gallery]=await Promise.all([import('./gallery.js'),loadStyle('gallery.css')]);return gallery},gallery=>gallery.showGallery({product:p,modal,esc,fa})));$('#shopSort').value=sort;renderShops();$('#shopSort').onchange=renderShops;$('#backCatalog').onclick=()=>{navigation++;if(!state.products.length&&!pageHasMore){search(state.query||p.category);return}showCatalog();requestAnimationFrame(()=>window.scrollTo({top:catalogScroll,behavior:'instant'}))};$('#editFilters').onclick=()=>{showCatalog();$('.filters').classList.add('is-open');$('#mobileFilters').setAttribute('aria-expanded','true');$('.filters').scrollIntoView({behavior:'smooth'})};$('#specsBtn').onclick=()=>modal(`<h2>مشخصات محصول</h2><p>${esc(p.title)}</p>${p.specs.length?`<div class="compare-table"><table>${p.specs.map(x=>`<tr><th>${esc(x.key)}</th><td>${esc(x.value)}</td></tr>`).join('')}</table></div>`:'<p>مشخصاتی در داده‌های این محصول ثبت نشده است.</p>'}`);$('#compareThis').onclick=()=>toggleCompare(p.id,true);market?.attach(p)}
function renderShops(){const os=ranked(state.selected);$('#shopList').innerHTML=os.length?os.map(shopCard).join(''):'<div class="empty"><b>فروشگاه منطبق باقی نمانده است</b><p>فیلترها را تغییر بده یا مدل مشابه انتخاب کن.</p><button id="similar">مدل‌های مشابه</button><button id="clearExclusions">برگرداندن فروشگاه‌های کنارگذاشته‌شده</button></div>';if($('#similar'))$('#similar').onclick=()=>{let q=state.selected.category;$('#query').value=q;search(q)};if($('#clearExclusions'))$('#clearExclusions').onclick=()=>{state.excluded.clear();renderShops()}}
function toggleCompare(id,on){companion?.comparisonChanged();let p=state.products.find(x=>x.id===id)||state.selected;if(on){if(!state.compare.some(x=>x.id===id)){if(state.compare.length>=3){toast('برای مقایسهٔ خوانا، حداکثر ۳ محصول انتخاب کن.');render();return}state.compare.push(p);toast('به مقایسه اضافه شد')}}else state.compare=state.compare.filter(x=>x.id!==id);$('#compareCount').textContent=fa(state.compare.length);companion?.refresh()}
$('#compareBtn').onclick=()=>{let ps=state.compare;if(ps.length<2){toast('حداقل دو محصول را برای مقایسه انتخاب کن.');return}let keys=[...new Set(ps.flatMap(p=>p.specs.map(s=>s.key)))].slice(0,15);modal(`<h2>مقایسهٔ گزینه‌های شما</h2><button id="compareWithAI" class="primary">کمک هوشمند برای انتخاب</button><p>قیمت، مشخصات و فروشنده‌ها؛ انتخاب نهایی با شماست.</p><div class="compare-table"><table><tr><th>محصول</th>${ps.map(p=>`<td>${img(p)}<p>${esc(p.title)}</p><button data-product="${p.id}">انتخاب این مدل</button></td>`).join('')}</tr><tr><th>شروع قیمت ثبت‌شده</th>${ps.map(p=>`<td>${price(p.min)}</td>`).join('')}</tr><tr><th>تعداد پیشنهاد فروش</th>${ps.map(p=>`<td>${fa(new Set(p.offers.map(o=>o.shop)).size)}</td>`).join('')}</tr>${keys.map(k=>`<tr><th>${esc(k)}</th>${ps.map(p=>`<td>${esc(p.specs.find(x=>x.key===k)?.value||'نامشخص')}</td>`).join('')}</tr>`).join('')}</table></div><p class="small">تفاوت نام و دسته‌بندی، به‌تنهایی به معنی برتری کیفیت نیست.</p>`);$('#compareWithAI').onclick=()=>openFeature('advisor',ui=>ui.open({products:ps}))};
function verification(id){const p=state.selected,s=shops[id],o=p.offers.find(x=>x.shop===id);modal(`<h2>پیش از حرکت، استعلام بگیر</h2><p>${esc(s.name)} · ${esc(p.title)}</p><div class="modal-note">شماره‌های دیتاست ساختگی‌اند؛ تماس خودکار غیرفعال است. هیچ تماس یا تأیید موجودی واقعی انجام نشده است. برای اتصال سرویس تماس، شمارهٔ معتبر و دسترسی سرویس لازم است.</div><h3>متن آمادهٔ پرسش از فروشگاه</h3><textarea id="callScript" readonly>سلام، برای خرید حضوری ${esc(p.title)} تماس گرفتم. قیمت ثبت‌شده ${fa(o.price||0)} تومان است. قیمت امروز و موجودی مدل دقیق را تأیید می‌کنید؟ رنگ، سایز یا گارانتی آن چیست؟ تا چه ساعتی باز هستید؟ آدرس دقیق طبقه، واحد و ورودی کجاست؟ آیا پرداخت اعتباری حضوری دارید و با چه شرایطی؟</textarea><div class="modal-actions"><button id="copyScript">کپی متن</button>${s.website_url&&/^https?:\/\//.test(s.website_url)?`<a href="${esc(s.website_url)}" target="_blank" rel="noopener" class="chip">وب‌سایت ثبت‌شده ↗</a>`:''}</div><label>نتیجهٔ پیگیری شما<textarea id="noteText" placeholder="مثلاً: پاسخ نداد، یا قیمت جدید و زمان مراجعه…"></textarea></label><p class="small">یادداشت شخصی در همین مرورگر ذخیره می‌شود و تأیید رسمی فروشگاه نیست.</p><div class="modal-actions"><button id="saveNote" class="primary">ذخیرهٔ نتیجهٔ پیگیری</button><button id="noAnswer">پاسخ نداد؛ جایگزین بده</button></div>`);$('#copyScript').onclick=async()=>{try{await navigator.clipboard.writeText($('#callScript').value);toast('متن کپی شد.')}catch{toast('متن را انتخاب و کپی کن.')}};$('#saveNote').onclick=()=>{let t=$('#noteText').value.trim();if(!t)return toast('نتیجهٔ پیگیری را بنویس.');state.notes[p.id+id]={text:t,at:new Date().toISOString()};storage.set('notes',state.notes);close();renderShops();$('#step3').classList.add('active')};$('#noAnswer').onclick=()=>fail(id)}
function fail(id){state.excluded.add(id);close();renderShops();toast('این فروشگاه از پیشنهادها کنار رفت؛ گزینهٔ بعدی بر اساس شرایط شما مرتب شد.');$('#shopList').scrollIntoView({behavior:'smooth'})}
function address(id){const s=shops[id],a=s.address||'',floor=a.match(/طبقه[^،,]{0,35}/)?.[0],unit=a.match(/واحد[^،,]{0,25}/)?.[0];modal(`<h2>تا درِ فروشگاه</h2><h3>${esc(s.name)}</h3><p>${esc(a||'آدرس ثبت نشده')}</p><div class="chips"><span class="chip">${esc(floor||'طبقه نامشخص')}</span><span class="chip">${esc(unit||'واحد نامشخص')}</span></div><div class="modal-note">طبقه و واحد از آدرس دیتاست استخراج شده‌اند. در صورت نامشخص بودن، از فروشنده بپرس. نام بیشتر فروشگاه‌ها ساختگی است؛ جستجو با آدرس انجام می‌شود.</div><div class="modal-actions"><a class="chip" target="_blank" rel="noopener" href="https://www.google.com/search?q=${encodeURIComponent(a+' آدرس پاساژ طبقه واحد')}">بررسی آدرس در گوگل ↗</a><a class="chip" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.lat&&s.lon?s.lat+','+s.lon:a)}">مشاهده روی نقشه ↗</a></div>`)}
function savePlan(id){const p=state.selected;if(state.plan.some(x=>x.product===p.id&&x.shop===id))return toast('این گزینه در برنامهٔ خرید هست.');state.plan.push({product:p.id,title:p.title,shop:id,at:new Date().toISOString()});storage.set('plan',state.plan);companion?.refresh();toast('در برنامهٔ خرید ذخیره شد.');$('#step3').classList.add('active')}
function plan(){if(state.plan.length&&!catalogReady){openDeferred(ensureCatalogData,plan);return}modal(`<h2>برنامهٔ خرید من</h2><p>گزینه‌های اصلی و جایگزین را برای مراجعه نگه دار.</p>${state.plan.length?state.plan.map((x,i)=>{let s=shops[x.shop];return `<article class="plan-item"><h3>${esc(x.title)}</h3><p>${esc(s?.name)} · ${esc(s?.address)}</p><p class="small">${esc(hours(s).text)} · موجودی تأیید نشده</p><div class="modal-actions"><button data-product="${x.product}">بازگشت به مقایسهٔ فروشگاه‌ها</button><button data-remove="${i}">حذف از برنامه</button></div></article>`}).join(''):'<div class="empty">هنوز گزینه‌ای ذخیره نکرده‌ای.<p>در صفحهٔ محصول، فروشگاه مناسب را در برنامه ذخیره کن.</p></div>'}<div class="modal-note">پیش از رفتن: مدل دقیق، قیمت، موجودی، ساعت مراجعه، طبقه و واحد و شرایط پرداخت را بررسی کن.</div>${state.plan.length?'<button data-route-plan class="primary">مسیر مراجعه به فروشگاه‌ها</button> <button id="exportPlan" class="outline">دریافت برنامهٔ خرید</button>':''}`);if($('#exportPlan'))$('#exportPlan').onclick=()=>{let text=state.plan.map(x=>{let s=shops[x.shop];return x.title+'\n'+s.name+'\n'+s.address+'\n'+hours(s).text+'\nموجودی تأیید نشده'}).join('\n\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='برنامه-خرید.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
function locationModal(){modal(`<h2>از کجا به خرید می‌روی؟</h2><p>فاصله‌ها بر اساس این نقطه محاسبه می‌شوند؛ فاصلهٔ مستقیم‌اند، نه زمان مسیریابی.</p><div class="choices">${[['مرکز شهر',35.7007,51.4091],['تجریش',35.804,51.4305],['صادقیه',35.721,51.3357],['ونک',35.757,51.409],['تهرانپارس',35.733,51.530]].map(x=>`<button data-point="${x[1]},${x[2]},${x[0]}">${x[0]}</button>`).join('')}</div><button id="gps" class="outline">⌖ استفاده از موقعیت فعلی من</button><p class="small">فقط با اجازهٔ مرورگر؛ مبدأ در این مرورگر ذخیره می‌شود. با درخواست مسیر، مختصات مبدأ و مقصد به سرویس مسیریابی ارسال می‌شوند.</p><label>عرض جغرافیایی<input id="lat" type="number" step="any" value="${state.point.lat}"></label><label>طول جغرافیایی<input id="lon" type="number" step="any" value="${state.point.lon}"></label><button id="savePoint" class="primary">ثبت نقطهٔ دلخواه</button>`);$('#savePoint').onclick=()=>setPoint(+$('#lat').value,+$('#lon').value,'نقطهٔ انتخابی');$('#gps').onclick=()=>{if(!navigator.geolocation)return toast('موقعیت‌یابی در این مرورگر پشتیبانی نمی‌شود.');navigator.geolocation.getCurrentPosition(p=>setPoint(p.coords.latitude,p.coords.longitude,'موقعیت من'),()=>toast('موقعیت در دسترس نیست؛ یک محله انتخاب کن.'),{timeout:10000})}}
function setPoint(lat,lon,label){if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return toast('مختصات معتبر وارد کن.');state.point={lat,lon,label};storage.set('point',state.point);$('#location span').textContent=label;close();render();if(state.selected&&!$('#detail').hidden)renderDetail()}
function guideModal(step=1){if(step===1){modal(`<h2>برای چه چیزی راهنمایی می‌خواهی؟</h2><p>۱ از ۲ · اول نیازت را مشخص کنیم.</p><div class="choices">${['کفش','گوشی موبایل','لپ تاپ','هدفون','ساعت','جاروبرقی'].map(c=>`<button data-gcat="${c}" class="${guide.category===c?'selected':''}">${c}</button>`).join('')}</div><label>یا دستهٔ دیگری بنویس<input id="customCategory" placeholder="مثلاً دوربین" value="${esc(guide.category)}"></label><button id="guideNext" class="primary">ادامه ←</button>`);$('#guideNext').onclick=()=>{guide.category=$('#customCategory').value.trim()||'کفش';guideModal(2)}}else{modal(`<h2>چه چیزی برایت مهم‌تر است؟</h2><p>۲ از ۲ · ${esc(guide.category)}</p><div class="choices">${['روزمره','ورزشی','کار و تحصیل','اقتصادی','کیفیت و امکانات'].map(c=>`<button data-guse="${c}" class="${guide.use===c?'selected':''}">${c}</button>`).join('')}</div><label>حداکثر بودجه (تومان)<input id="guideBudget" type="number" min="0" placeholder="مثلاً ۵۰۰۰۰۰۰" value="${esc(guide.budget)}"></label><p class="modal-note">راهنما بر اساس دسته، واژه‌های کاربرد و بودجه جستجو می‌کند؛ کیفیت یا تناسب پزشکی محصول را از روی نام حدس نمی‌زند. برای انتخاب نهایی، مشخصات گزینه‌ها را مقایسه کن.</p><div class="modal-actions"><button id="guideResults" class="primary">پیدا کردن گزینه‌های مناسب</button><button id="guideBack">مرحلهٔ قبل</button></div>`);$('#guideBack').onclick=()=>guideModal(1);$('#guideResults').onclick=async()=>{guide.budget=$('#guideBudget').value;$('#budget').value=guide.budget;let q=guide.category;if(q==='کفش'&&guide.use==='ورزشی')q='کفش ورزشی';if(q==='لپ تاپ')q='لپ';$('#query').value=q;if(guide.use==='اقتصادی')$('#productSort').value='cheap';close();await search(q);toast('گزینه‌ها با دسته و بودجهٔ شما پیدا شدند؛ دو مدل را برای مقایسه انتخاب کن.')}}}
function reset(){visitPicker.reset();for(let s of ['#budget','#visitTime'])$(s).value='';$('#radius').value='100';$('#credit').checked=false;$('#openOnly').checked=false;state.excluded.clear();search($('#query').value.trim())}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.query!==undefined){$('#query').value=el.dataset.query;search(el.dataset.query)}if(el.dataset.product){close();openProduct(el.dataset.product)}if(el.dataset.verify)verification(el.dataset.verify);if(el.dataset.kitShop){const p=state.selected;openFeature('kit',ui=>ui.open(p,el.dataset.kitShop))}if(el.dataset.routeShop)openFeature('routing',ui=>ui.show([el.dataset.routeShop]));if(el.hasAttribute('data-route-plan'))openFeature('routing',ui=>ui.show(state.plan.map(p=>p.shop)));if(el.dataset.address)address(el.dataset.address);if(el.dataset.save)savePlan(el.dataset.save);if(el.dataset.fail)fail(el.dataset.fail);if(el.hasAttribute('data-reset'))reset();if(el.dataset.point){let [a,b,c]=el.dataset.point.split(',');setPoint(+a,+b,c)}if(el.dataset.gcat){guide.category=el.dataset.gcat;guideModal(1)}if(el.dataset.guse){guide.budget=$('#guideBudget').value;guide.use=el.dataset.guse;guideModal(2)}if(el.dataset.remove!==undefined){state.plan.splice(+el.dataset.remove,1);storage.set('plan',state.plan);companion?.refresh();plan()}});
document.addEventListener('change',e=>{if(e.target.dataset.compare)toggleCompare(e.target.dataset.compare,e.target.checked)});
$('#browseCatalog').onclick=()=>search($('#homeQuery').value.trim());
$('#homeSearchForm').onsubmit=e=>{e.preventDefault();search($('#homeQuery').value.trim());window.scrollTo({top:0})};$('#searchForm').onsubmit=e=>{e.preventDefault();search($('#query').value.trim())};$('#apply').onclick=()=>{if(!visitPicker.valid())return;search($('#query').value.trim());if(matchMedia('(max-width:800px)').matches){$('.filters').classList.remove('is-open');$('#mobileFilters').setAttribute('aria-expanded','false')}toast('فیلترها اعمال شد.')};$('#reset').onclick=reset;$('#productSort').onchange=()=>search(state.query);$('#more').onclick=loadMore;$('#location').onclick=locationModal;$('#savedTop').onclick=plan;$('#mobileSaved').onclick=plan;$('#startGuide').onclick=()=>guideModal();$('#guideAgain').onclick=()=>guideModal();$('.brand').onclick=e=>{e.preventDefault();navigation++;state.seq++;searchAbort?.abort();showCatalog();document.body.classList.add('home');window.scrollTo({top:0,behavior:'smooth'})};$('#theme').onclick=()=>{document.body.classList.toggle('dark');const dark=document.body.classList.contains('dark');storage.set('reference-dark',dark);$('#theme').setAttribute('aria-pressed',String(dark))};const dark=storage.get('reference-dark',true);document.body.classList.toggle('dark',dark);$('#theme').setAttribute('aria-pressed',String(dark));
$('#allCats').onclick=()=>openDeferred(ensureMeta,()=>modal(`<h2>دسته‌بندی‌های دیتاست</h2><p>یک دسته را برای جستجو انتخاب کن.</p><div class="choices">${(meta.categories||[]).slice(0,150).map(x=>`<button data-query="${esc(x[0])}" onclick="document.querySelector('#modal').close()">${esc(x[0])} <small>(${fa(x[1])})</small></button>`).join('')}</div>`));
$('#about').onclick=()=>openDeferred(ensureMeta,()=>modal(`<h2>شفافیت اطلاعات</h2><p>این پروژه نمونهٔ مستقل خرید حضوری است.</p><div class="modal-note">${fa(meta.products)} محصول، ${fa(meta.offers)} پیشنهاد و ${fa(meta.shops)} فروشگاه از دیتاست رسمی v16.</div><p>قیمت‌ها ثبت‌شده‌اند و موجودی زنده نیست. تمام شماره‌ها و بیشتر نام‌ها ساختگی‌اند. تماس واقعی، تأیید خودکار و جستجوی خودکار گوگل در این نسخه متصل نیستند. پیگیری شما با برچسب یادداشت شخصی ذخیره می‌شود.</p><p>پیشنهاد متعادل: ۴۵٪ نسبت قیمت به کمینه، ۳۵٪ فاصلهٔ مستقیم، ۲۰٪ سازگاری با ساعت مراجعه. فیلتر اعتبار فقط اطلاعات حضوری صریح را می‌پذیرد. برنامهٔ خرید و موقعیت در مرورگر نگه داشته می‌شوند؛ پیام گفتگو در حالت اتصال مدل به سرور ارسال می‌شود. پیوندهای نقشه و گوگل هنگام باز کردن، مقصد را به همان سرویس می‌فرستند.</p>`));
$('#mobileFilters').onclick=()=>{const open=$('.filters').classList.toggle('is-open');$('#mobileFilters').setAttribute('aria-expanded',String(open));if(open)$('.filters').scrollIntoView({behavior:'smooth',block:'nearest'})};
$('#askAdvisor').onclick=()=>openFeature('advisor',ui=>ui.open());
document.querySelector('.landing-footer').addEventListener('click',e=>{const id=e.target.closest('[data-home-action]')?.dataset.homeAction;if(id)$('#'+id)?.click()});
async function ensureMeta(){if(!Object.keys(meta).length)meta=await json('data/meta.json');return meta}
async function ensureCatalogData(){
 if(catalogReady)return;if(catalogPromise)return catalogPromise;
 catalogPromise=(async()=>{
  const [loadedShops,,{initCompanion},{initMarket}]=await Promise.all([json('data/shops.json'),ensureMeta(),import('./companion.js'),import('./market.js'),loadStyle('companion.css')]);shops=loadedShops;
  companion=initCompanion({state,storage,$,esc,fa,icon,modal,toast,openProduct,search,toggleCompare,meta});market=initMarket({state,storage,$,esc,fa,modal,toast,shops,openProduct});catalogReady=true;
  $('#dataInfo').textContent=`${fa(meta.products)} محصول · ${fa(meta.offers)} پیشنهاد · ${fa(meta.shops)} فروشگاه، نسخهٔ ۱۶؛ دادهٔ غیرزنده.`;
  if(companion.restoreIds.length){try{companion.restoreCompare(await getProducts(companion.restoreIds))}catch{toast('بازیابی مقایسه فعلاً ممکن نشد؛ انتخاب‌های ذخیره‌شده حفظ شدند.')}}
 })().catch(e=>{catalogPromise=null;throw e});return catalogPromise;
}
async function openDeferred(load,show){
 modal('<p role="status" aria-live="polite">در حال آماده‌سازی…</p>');const epoch=modalEpoch;
 try{const value=await load();if(epoch===modalEpoch&&$('#modal').open)show(value)}catch{if(epoch!==modalEpoch||!$('#modal').open)return;modal('<p role="alert">این بخش دریافت نشد. انتخاب‌هایت حفظ شده‌اند.</p><button id="retryFeature" class="primary">تلاش دوباره</button>');$('#retryFeature').onclick=()=>openDeferred(load,show)}
}
function feature(name){
 if(!features.has(name)){const promise=(async()=>{
  if(name==='advisor'){const [{initAdvisorUI}]=await Promise.all([import('./advisor-ui.js'),loadStyle('advisor-ui.css')]);return initAdvisorUI({state,$,esc,fa,modal,toast,search,close,parseAmount})}
  if(name==='kit'){const [{initVisitKit}]=await Promise.all([import('./visit-kit.js'),loadStyle('visit-kit.css')]);return initVisitKit({state,storage,$,esc,fa,modal,toast,shops})}
  const {initRouting}=await import('./routing.js');return initRouting({state,shops,$,esc,fa,modal,toast,locationModal});
 })().catch(e=>{features.delete(name);throw e});features.set(name,promise)}return features.get(name);
}
function openFeature(name,show){return openDeferred(()=>feature(name),show)}
async function init(){
 $('#location span').textContent=state.point.label;$('#status').textContent='قیمت ثبت‌شده · موجودی پیش از مراجعه استعلام شود';
 const initialNav=navigation,params=new URLSearchParams(location.search),initialProduct=params.get('product'),initialQuery=params.get('q');if(params.has('budget'))$('#budget').value=parseAmount(params.get('budget'));
 if(initialQuery){await search(initialQuery);if(navigation!==initialNav+1)return}if(initialProduct)await openProduct(initialProduct);
}
init();
